$passed=0;$failed=0;
function check(bool $condition,string $name): void {global $passed,$failed;if($condition){$passed++;echo "PASS  $name\n";}else{$failed++;echo "FAIL  $name\n";}}
function db(): PDO {global $serviceDb;return $serviceDb;}
function db_is_sqlite(): bool{return true;}
function sql_now(): string{return "datetime('now')";}
function query_one(string $sql,array $params=[]): ?array{$s=db()->prepare($sql);$s->execute($params);$row=$s->fetch(PDO::FETCH_ASSOC);return $row?:null;}
