check(EditorialWorkflow::allows('editor','pitch.review')&&EditorialWorkflow::allows('editor','assignment.manage'),'editor can review pitches and manage assignments');
check(!EditorialWorkflow::allows('system_administrator','pitch.review'),'system administrator cannot review editorial pitches');
