check(!EditorialWorkflow::canTransition('editor','under_review','approved',['author_id'=>7,'actor_id'=>7]),'author cannot approve own article');
check(!EditorialWorkflow::canTransition('editor','under_review','approved',['author_id'=>7,'actor_id'=>8,'risk_level'=>'high','fact_check_outcome'=>'failed']),'high-risk article requires fact-check');
check(EditorialWorkflow::canTransition('editor','under_review','approved',['author_id'=>7,'actor_id'=>8,'risk_level'=>'standard']),'separate editor can approve standard article');
check(!EditorialWorkflow::canTransition('editor','under_review','approved',['author_id'=>7,'actor_id'=>8,'risk_level'=>'standard','source_classification_complete'=>0]),'incomplete source classification blocks approval');
check(!EditorialWorkflow::canTransition('editor','under_review','approved',['author_id'=>7,'actor_id'=>8,'risk_level'=>'standard','source_classification_complete'=>1,'confidential_data_protected'=>0]),'plaintext confidential data blocks approval');
check(!EditorialWorkflow::canTransition('editor','approved','published',['approved_by'=>8,'fact_check_required'=>1,'fact_check_outcome'=>'failed']),'failed required fact-check blocks publish');
check(EditorialWorkflow::canTransition('editor','approved','published',['approved_by'=>8,'fact_check_required'=>1,'fact_check_outcome'=>'passed']),'passed required fact-check permits publish');
check(!EditorialWorkflow::canTransition('editor','approved','published',['fact_check_outcome'=>'passed']),'publication requires recorded approver');
check(!EditorialWorkflow::canTransition('editor','under_review','approved',['author_id'=>7,'actor_id'=>8,'legal_outcome'=>'failed']),'any failed specialist check blocks approval');
check(EditorialWorkflow::canTransition('editor','under_review','approved',['author_id'=>7,'actor_id'=>8,'risk_level'=>'high','sources_outcome'=>'passed','fairness_outcome'=>'passed','fact_check_outcome'=>'passed','legal_outcome'=>'passed','right_of_reply_status'=>'not_applicable','right_of_reply_outcome'=>'not_applicable']),'high-risk gates pass only with required evidence');
check(!EditorialWorkflow::canTransition('editor','under_review','approved',['author_id'=>7,'actor_id'=>8,'risk_level'=>'standard','media_count'=>1,'media_all_approved'=>0,'media_rights_outcome'=>'passed']),'pending media blocks approval');
check(EditorialWorkflow::canTransition('editor','under_review','approved',['author_id'=>7,'actor_id'=>8,'risk_level'=>'standard','media_count'=>1,'media_all_approved'=>1,'media_rights_outcome'=>'passed']),'approved media with rights check permits approval');
check(!EditorialWorkflow::canTransition('editor','approved','published',['approved_by'=>8,'author_id'=>7,'actor_id'=>8,'risk_level'=>'critical','sources_outcome'=>'passed','fairness_outcome'=>'passed','fact_check_outcome'=>'passed','legal_outcome'=>'passed','right_of_reply_status'=>'not_applicable','right_of_reply_outcome'=>'not_applicable']),'critical-risk approver cannot also publish');
