$key='base64:'.base64_encode(str_repeat('k',32));$plain="Source: protected person\nPhone: +250000000";$cipher=Security::encrypt($plain,$key);
check(str_starts_with($cipher,'v2.primary.')&&!str_contains($cipher,'protected person'),'source note is encrypted at rest with key identifier');
check(Security::decrypt($cipher,$key)===$plain,'encrypted source note decrypts with correct key');
$legacyIv=random_bytes(12);$legacyTag='';$legacyCipher=openssl_encrypt($plain,'aes-256-gcm',str_repeat('k',32),OPENSSL_RAW_DATA,$legacyIv,$legacyTag,implode('',['UM','URONGO']).':v2:primary');$legacyEnvelope='v2.primary.'.base64_encode($legacyIv).'.'.base64_encode($legacyTag).'.'.base64_encode((string)$legacyCipher);check(Security::decrypt($legacyEnvelope,$key)===$plain,'legacy source envelope remains decryptable after brand migration');
try{Security::decrypt($cipher,'base64:'.base64_encode(str_repeat('x',32)));check(false,'wrong key rejects source note');}catch(RuntimeException){check(true,'wrong key rejects source note');}
$rotated=Security::encrypt($plain,['old'=>$key,'next'=>'base64:'.base64_encode(str_repeat('n',32))],'next');check(Security::decrypt($rotated,['old'=>$key,'next'=>'base64:'.base64_encode(str_repeat('n',32))])===$plain,'key ring decrypts rotated envelope');
$secret=Security::base32Encode(str_repeat("\x01",20));$code=Security::totp($secret,time());check(Security::verifyTotp($secret,$code),'TOTP MFA code verifies');check(!Security::verifyTotp($secret,'00000'),'malformed MFA code rejected');
